package complete

import "gorm.io/gorm"

type targetState int

const (
	targetEmpty    targetState = iota // no patient: generation allowed
	targetComplete                    // demo-complete dataset already present: validate only
	targetForeign                     // patients that demo-complete did not create: refused
)

// MarkerEmail is the first account created by --demo-complete; its presence together with
// patients identifies a database generated by this seeder (patient codes are assigned by
// the patients service itself, so they cannot carry a seeder prefix).
const MarkerEmail = StaffEmailPrefix + "direction.medicale" + StaffEmailDomain

// inspectTarget implements the dataset-level guard that complements the common demo guard
// of cmd/seed: --demo-complete only generates into a database without any patient. A
// database whose patients were not created by --demo-complete (real records, legacy demo
// seeds) is refused whatever the opt-ins, so the volumetric dataset is never mixed with
// other records. Re-running on a generated database only re-validates it.
func inspectTarget(db *gorm.DB) (targetState, error) {
	var patients, marker int64
	if err := db.Table("patients").Count(&patients).Error; err != nil {
		return 0, err
	}
	if patients == 0 {
		return targetEmpty, nil
	}
	if err := db.Table("users").Where("email = ?", MarkerEmail).Count(&marker).Error; err != nil {
		return 0, err
	}
	if marker > 0 {
		return targetComplete, nil
	}
	return targetForeign, nil
}
